function climbStairs(n) {
  const dp = [1, 1];           // dp[0]=1(아무것도 안 오름), dp[1]=1(한 칸)
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];  // 마지막에 1칸 또는 2칸 오른 경우의 합
  }
  return dp[n];
}

